<?php require_once __DIR__.'/../includes/auth.php'; require_login(); $id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM surveys WHERE id=?');$s->execute([$id]);$survey=$s->fetch();if(!$survey){http_response_code(404);exit('Survey not found');}$q=db()->prepare('SELECT * FROM survey_questions WHERE survey_id=? ORDER BY sort_order,id');$q->execute([$id]);$questions=$q->fetchAll();foreach($questions as &$question){$o=db()->prepare('SELECT * FROM question_options WHERE question_id=? ORDER BY sort_order,id');$o->execute([$question['id']]);$question['options']=$o->fetchAll();}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preview — <?=e($survey['title'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="survey-shell px-3"><div class="alert alert-warning">Preview mode — responses cannot be submitted.</div><div class="panel bg-white p-4 p-md-5"><h1 class="fw-bold"><?=e($survey['title'])?></h1><p class="text-secondary"><?=nl2br(e($survey['description']))?></p><hr><?php foreach($questions as $i=>$question):?><div class="mb-4"><label class="form-label fw-semibold"><?=($i+1)?>. <?=e($question['question_text'])?><?=$question['required']?' <span class="text-danger">*</span>':''?></label><?php if(in_array($question['question_type'],['single','multiple'])):?><?php foreach($question['options'] as $opt):?><div class="form-check"><input class="form-check-input" type="<?=$question['question_type']==='single'?'radio':'checkbox'?>" disabled><label class="form-check-label"><?=e($opt['option_text'])?></label></div><?php endforeach;?><?php elseif($question['question_type']==='dropdown'):?><select class="form-select" disabled><option>Select…</option><?php foreach($question['options'] as $opt):?><option><?=e($opt['option_text'])?></option><?php endforeach;?></select><?php elseif($question['question_type']==='rating'):?><div class="btn-group"><?php for($n=1;$n<=5;$n++):?><button class="btn btn-outline-primary" disabled><?=$n?></button><?php endfor;?></div><?php elseif($question['question_type']==='yesno'):?><div><span class="btn btn-outline-secondary disabled">Yes</span> <span class="btn btn-outline-secondary disabled">No</span></div><?php elseif($question['question_type']==='long_text'):?><textarea class="form-control" rows="4" disabled></textarea><?php else:?><input class="form-control" disabled><?php endif;?></div><?php endforeach;?></div></div></body></html>